n = int(input())
and_op = 1023  # All bits set to 1
or_op = 0  # All bits set to 0
xor_op = 0  # No change

for _ in range(n):
    op, x = input().split()
    x = int(x)
    if op == '&':
        and_op &= x
        or_op &= x
    elif op == '|':
        or_op |= x
        and_op |= x
    elif op == '^':
        xor_op ^= x
        and_op &= ~x
        or_op |= x

# Determine the simplified operations
and_final = 1023
or_final = 0
xor_final = 0

# Calculate the final values for AND, OR, and XOR
for i in range(10):
    if and_op & (1 << i):
        and_final &= ~(1 << i)
    if not or_op & (1 << i):
        or_final &= ~(1 << i)
    if xor_op & (1 << i):
        xor_final ^= (1 << i)

# Determine the number of operations needed
operations = []
if and_final != 1023:
    operations.append('& ' + str(and_final))
if or_final != 0:
    operations.append('| ' + str(or_final))
if xor_final != 0:
    operations.append('^ ' + str(xor_final))

print(len(operations))
for op in operations:
